package service

import "github.com/Bob-xisuke/orb-scheduler-core/internal/model"

// schedule performs the trial placement. Among nodes whose labels contain
// every selector pair and whose CPU and memory capacities both fit the
// request, it picks the name that is smallest in UTF-8 byte order. Capacity
// is only probed and never deducted; priority does not affect the choice.
// It returns the record's status together with its node and reason fields:
// placed with the chosen node and no reason, or rejected with no node and
// reason no_eligible_node. An empty candidate list rejects like any list
// without an eligible node.
func schedule(p *model.Placement) (status string, node *string, reason *string) {
	var chosen string
	found := false
	for i := range p.Nodes {
		n := &p.Nodes[i]
		if !labelsContain(n.Labels, p.Selector) {
			continue
		}
		if n.CPU < p.Resources.CPU || n.Memory < p.Resources.Memory {
			continue
		}
		if !found || n.Name < chosen {
			chosen = n.Name
			found = true
		}
	}
	if found {
		n := chosen
		return StatusPlaced, &n, nil
	}
	r := ReasonNoNode
	return StatusRejected, nil, &r
}

// labelsContain reports whether labels holds every selector key with the same
// value.
func labelsContain(labels, selector map[string]string) bool {
	for key, want := range selector {
		if got, ok := labels[key]; !ok || got != want {
			return false
		}
	}
	return true
}

// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"fmt"

	_ "modernc.org/sqlite"
)

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	// Serialize access through one connection: combined with WAL this keeps
	// concurrent submissions free of busy errors while the UNIQUE constraint
	// remains the guarantee that one identity is stored exactly once.
	db.SetMaxOpenConns(1)
	if _, err := db.Exec("PRAGMA busy_timeout=5000"); err != nil {
		db.Close()
		return nil, fmt.Errorf("set busy timeout: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS placements (
	namespace  TEXT NOT NULL,
	name       TEXT NOT NULL,
	input_json TEXT NOT NULL,
	status     TEXT NOT NULL,
	node       TEXT,
	reason     TEXT,
	queue      TEXT NOT NULL GENERATED ALWAYS AS (json_extract(input_json, '$.queue')) VIRTUAL,
	PRIMARY KEY (namespace, name)
);

CREATE INDEX IF NOT EXISTS idx_placements_ns   ON placements (namespace);
CREATE INDEX IF NOT EXISTS idx_placements_queue ON placements (queue);
CREATE INDEX IF NOT EXISTS idx_placements_node  ON placements (node);
`

package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
	"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
)

// NewRouter wires the public HTTP surface: health and the placements API. Every
// entry keeps the error shape described in README.md.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	h := &placementHandler{svc: service.New(st)}
	router.POST("/v1/placements", h.createPlacement)
	router.GET("/v1/placements", h.listPlacements)

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

package store

import "github.com/Bob-xisuke/orb-scheduler-core/internal/model"

// Compatibility re-exports. The record model, the defaulting and
// content-equality rules, and the storage-contract vocabulary live in
// internal/model so that parsing, scheduling and idempotency judgment — and
// in-memory storage doubles — never depend on this package's SQLite driver.
// Existing callers that refer to these names through package store keep
// working unchanged: the aliases are the very same types and functions.

type (
	// Placement is one stored scheduling decision; see model.Placement.
	Placement = model.Placement
	// Node is one candidate node offered by a placement request.
	Node = model.Node
	// Resources is a workload request or a node capacity.
	Resources = model.Resources
	// ListFilter narrows List; empty fields are ignored. Node never matches
	// a rejected record.
	ListFilter = model.ListFilter
)

// ErrNotFound is returned by Get when no placement matches the identity.
var ErrNotFound = model.ErrNotFound

// NormalizeInput fills the documented omitted-field defaults in place; see
// model.NormalizeInput, the single definition shared by every entry point.
var NormalizeInput = model.NormalizeInput

// SameInput reports whether the request halves of two placements are equal
// under the documented comparison; see model.SameInput.
var SameInput = model.SameInput

