327		if len(decodeBody(t, byNamespace)["items"].([]any)) != 2 {
328			t.Fatalf("namespace filter: %s", byNamespace.Body.String())
329		}
330		empty := doRequest(t, h, http.MethodGet, "/v1/placements?queue=nope", "")
331		if got := decodeBody(t, empty)["items"].([]any); len(got) != 0 {
332			t.Fatalf("want empty items, got %v", got)
333		}
