495		}
496		if err := st.Close(); err != nil {
497			t.Fatalf("close: %v", err)
498		}
499	
500		st2, err := store.Open(path)
501		if err != nil {
502			t.Fatalf("reopen: %v", err)
503		}
504		defer st2.Close()
505		h2 := NewRouter(st2)
506		rec := doRequest(t, h2, http.MethodGet, "/v1/placements?namespace=team-a&name=job-1", "")
507		if rec.Code != http.StatusOK {
508			t.Fatalf("get after reopen = %d: %s", rec.Code, rec.Body.String())
509		}
510		if got := decodeBody(t, rec); got["status"] != "placed" || got["node"] != "node-a" {
511			t.Fatalf("record changed across reopen: %s", rec.Body.String())
512		}
513	}
514	
515	// A resubmission that differs only textually — members reordered, member
516	// names written with Unicode escapes, omitted defaults spelled out — carries
517	// the same content: 200 with the original record, not a new one.
518	func TestTextualVariantResubmissionReturnsOriginal(t *testing.T) {
519		_, h := newTestRouter(t)
520		first := postPlacement(t, h, `{
521		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
522		  "resources": {"cpu": 100, "memory": 64},
523		  "nodes": [{"name": "n", "cpu": 200, "memory": 128}]
524		}`)
525		if first.Code != http.StatusCreated {
526			t.Fatalf("first = %d: %s", first.Code, first.Body.String())
527		}
528		variant := postPlacement(t, h, `{
529		  "nodes": [{"lab\u0065ls": {}, "memory": 128, "cpu": 200, "name": "n"}],
530		  "resour\u0063es": {"memory": 64, "cpu": 100},
531		  "selector": {},
532		  "priority": 1, "queue": "q", "name": "job", "namespac\u0065": "ns"
533		}`)
534		if variant.Code != http.StatusOK {
535			t.Fatalf("variant = %d, want 200: %s", variant.Code, variant.Body.String())
536		}
537		if variant.Body.String() != first.Body.String() {
